blocks.referenceSolution:
CREATE TABLE coaches (
  id INTEGER PRIMARY KEY,
  name TEXT
);
INSERT INTO coaches VALUES (1, 'Reed'), (2, 'Diaz');
CREATE TABLE teams (
  id INTEGER PRIMARY KEY,
  name TEXT,
  coach_id INTEGER REFERENCES coaches(id)
);
INSERT INTO teams VALUES (1, 'Falcons', 1), (2, 'Wolves', 1), (3, 'Lions', 2);
SELECT teams.name AS team, coaches.name AS coach
FROM teams JOIN coaches ON teams.coach_id = coaches.id
ORDER BY teams.id;

