CREATE TABLE games (id INTEGER, title TEXT);
CREATE TABLE sales (id INTEGER, game_id INTEGER, copies INTEGER);
INSERT INTO games VALUES (1,'Rift'),(2,'Tidepool');
INSERT INTO sales VALUES (1,1,50),(2,1,20),(3,2,10);
SELECT games.title, SUM(sales.copies) AS total_copies
FROM games
JOIN sales ON sales.game_id = games.id
GROUP BY games.title
ORDER BY total_copies DESC;

